const siren=(cx,cy,r)=>`<circle cx="${cx}" cy="${cy}" r="${r}" fill="${GREEN}"/>
<g clip-path="${ref('sirenclip')}"><path d="${SIREN}" transform="translate(${cx} ${cy}) scale(${r2(r/50)})" fill="#fff" fill-rule="evenodd"/></g>`;
const sirenDefs=(cx,cy,r)=>`<clipPath id="__ID__sirenclip"><circle cx="${cx}" cy="${cy}" r="${r}"/></clipPath>`;
const mark=(d,x,y,sx,sy,fill)=>`<path d="${d}" transform="translate(${x} ${y}) scale(${sx} ${sy})" fill="${fill}" fill-rule="evenodd"/>`;

// Smooth curve through points (Catmull-Rom as cubic Beziers), continuing from the first point.
function through(pts) {
  let d='';
  for (let i=0;i<pts.length-1;i++) {
    const p0=pts[Math.max(i-1,0)],p1=pts[i],p2=pts[i+1],p3=pts[Math.min(i+2,pts.length-1)];
    d+=`C${r2(p1[0]+(p2[0]-p0[0])/6)} ${r2(p1[1]+(p2[1]-p0[1])/6)} ${r2(p2[0]-(p3[0]-p1[0])/6)} ${r2(p2[1]-(p3[1]-p1[1])/6)} ${r2(p2[0])} ${r2(p2[1])}`;
  }
  return d;
}

